/**
 * Unit tests for the replay harness (PLAN.md §13 M0, §21.4).
 *
 * These run against the committed fixture in `fixtures/`, which is generated by
 * the real simulator geometry. That makes this file both a test of the parser
 * and a check that the checked-in fixture is still well-formed — a fixture that
 * silently rots would otherwise only fail during play.
 */

import { describe, expect, it } from 'vitest';

import fixture from '../../fixtures/replay-sweep.json';
import { LANDMARK_COUNT, Landmark } from '../tracking/landmarkTypes';
import { parseReplayClip, ReplayClipError, ReplaySource } from './replaySource';

describe('the committed fixture', () => {
  it('parses and reports its own provenance honestly', () => {
    const clip = parseReplayClip(fixture);
    expect(clip.name).toBe('sweep-and-web-gesture');
    expect(clip.fps).toBe(24);
    expect(clip.sourceWidth).toBe(640);
    expect(clip.sourceHeight).toBe(480);
    expect(clip.frames.length).toBe(24);
    // Synthetic, not recorded from a camera. Must never claim 'observed'.
    expect(clip.provenance).toBe('simulated');
  });

  it('contains one complete hand per frame, with a stated handedness score', () => {
    const clip = parseReplayClip(fixture);
    for (const frame of clip.frames) {
      expect(frame.hands).toHaveLength(1);
      const hand = frame.hands[0]!;
      expect(hand.landmarks).toHaveLength(LANDMARK_COUNT);
      expect(hand.handedness.label).toBe('Right');
      expect(hand.handedness.score).toBeGreaterThan(0);
      expect(hand.handedness.score).toBeLessThanOrEqual(1);
      for (const lm of hand.landmarks) {
        expect(Number.isFinite(lm.x)).toBe(true);
        expect(Number.isFinite(lm.y)).toBe(true);
      }
    }
  });

  it('carries no per-hand confidence fields beyond the model outputs (§5.1)', () => {
    const clip = parseReplayClip(fixture);
    for (const hand of clip.frames.flatMap((frame) => frame.hands)) {
      expect(Object.keys(hand).sort()).toEqual(['handedness', 'landmarks']);
      expect(Object.keys(hand.handedness).sort()).toEqual(['label', 'score']);
      // z is omitted from the fixture entirely (PLAN.md §8 Rule C).
      expect(hand.landmarks.every((lm) => lm.z === undefined)).toBe(true);
    }
  });

  it('moves the hand across the clip, so replay is visibly animated', () => {
    const clip = parseReplayClip(fixture);
    const first = clip.frames[0]!.hands[0]!.landmarks[Landmark.WRIST]!;
    const last = clip.frames[clip.frames.length - 1]!.hands[0]!.landmarks[
      Landmark.WRIST
    ]!;
    expect(last.x).toBeGreaterThan(first.x + 0.2);
  });

  it('folds the middle and ring fingers part-way through the clip', () => {
    const clip = parseReplayClip(fixture);
    const spread = (frameIndex: number): number => {
      const hand = clip.frames[frameIndex]!.hands[0]!;
      const wrist = hand.landmarks[Landmark.WRIST]!;
      const middleTip = hand.landmarks[Landmark.MIDDLE_TIP]!;
      return Math.hypot(middleTip.x - wrist.x, middleTip.y - wrist.y);
    };
    // Open at the start, folded in the middle, open again at the end.
    expect(spread(0)).toBeGreaterThan(spread(12));
    expect(spread(23)).toBeGreaterThan(spread(12));
  });

  it('derives duration from the last timestamp plus one frame interval', () => {
    const clip = parseReplayClip(fixture);
    const lastT = clip.frames[clip.frames.length - 1]!.timestampMs;
    expect(clip.durationMs).toBeCloseTo(lastT + 1000 / 24, 6);
    expect(clip.durationMs).toBeLessThan(1000);
  });
});

/** A minimal valid clip, loose-typed so individual fields can be broken. */
function validClipInput(): Record<string, unknown> {
  const landmarks = Array.from({ length: LANDMARK_COUNT }, (_, i) => [
    0.4 + i * 0.001,
    0.6,
  ]);
  return {
    name: 'unit-clip',
    fps: 10,
    source: { width: 640, height: 480 },
    frames: [
      {
        t: 0,
        hands: [
          { handedness: 'Right', handednessScore: 0.9, landmarks: [...landmarks] },
        ],
      },
      {
        t: 100,
        hands: [
          { handedness: 'Left', handednessScore: 0.8, landmarks: [...landmarks] },
        ],
      },
    ],
  };
}

function framesOf(input: Record<string, unknown>): Array<Record<string, unknown>> {
  return input['frames'] as Array<Record<string, unknown>>;
}

function firstHandOf(input: Record<string, unknown>): Record<string, unknown> {
  const hands = framesOf(input)[0]!['hands'] as Array<Record<string, unknown>>;
  return hands[0]!;
}

describe('parseReplayClip validation', () => {
  it('accepts a minimal well-formed clip and defaults provenance to simulated', () => {
    const clip = parseReplayClip(validClipInput());
    expect(clip.provenance).toBe('simulated');
    expect(clip.durationMs).toBeCloseTo(200, 6); // t=100 + one 10fps frame
  });

  it('preserves an explicit observed provenance rather than rewriting it', () => {
    const input = validClipInput();
    input['provenance'] = 'observed';
    expect(parseReplayClip(input).provenance).toBe('observed');
  });

  it('rejects non-object roots', () => {
    for (const bad of [null, undefined, 42, 'clip', []]) {
      expect(() => parseReplayClip(bad)).toThrow(ReplayClipError);
    }
  });

  it('rejects missing or malformed fields with a path-qualified message', () => {
    const cases: Array<[string, (input: Record<string, unknown>) => void, RegExp]> = [
      ['name', (i) => { delete i['name']; }, /clip\.name/],
      ['fps', (i) => { i['fps'] = 0; }, /clip\.fps/],
      ['fps type', (i) => { i['fps'] = '24'; }, /clip\.fps/],
      ['source', (i) => { delete i['source']; }, /clip\.source/],
      ['source width', (i) => { i['source'] = { width: 0, height: 480 }; }, /clip\.source\.width/],
      ['frames missing', (i) => { delete i['frames']; }, /clip\.frames/],
      ['frames empty', (i) => { i['frames'] = []; }, /clip\.frames/],
      ['frame timestamp', (i) => { framesOf(i)[0]!['t'] = 'zero'; }, /frames\[0\]\.t/],
      ['frame hands', (i) => { delete framesOf(i)[0]!['hands']; }, /frames\[0\]\.hands/],
      ['provenance', (i) => { i['provenance'] = 'made-up'; }, /clip\.provenance/],
    ];
    for (const [label, mutate, pattern] of cases) {
      const input = validClipInput();
      mutate(input);
      expect(() => parseReplayClip(input), label).toThrow(pattern);
    }
  });

  it('requires exactly 21 landmarks per hand and names the offender', () => {
    const input = validClipInput();
    const landmarks = firstHandOf(input)['landmarks'] as number[][];
    landmarks.pop();
    expect(() => parseReplayClip(input)).toThrow(/frames\[0\]\.hands\[0\]\.landmarks/);
  });

  it('rejects a non-finite or non-numeric landmark', () => {
    for (const bad of [['a', 0.5], [Number.NaN, 0.5], [0.5], [0.5, Number.POSITIVE_INFINITY]]) {
      const input = validClipInput();
      const landmarks = firstHandOf(input)['landmarks'] as unknown[];
      landmarks[3] = bad;
      expect(() => parseReplayClip(input)).toThrow(ReplayClipError);
    }
  });

  it('rejects an unknown handedness label', () => {
    const input = validClipInput();
    firstHandOf(input)['handedness'] = 'Sideways';
    expect(() => parseReplayClip(input)).toThrow(/handedness/);
  });

  it('requires a handedness score rather than inventing one', () => {
    const input = validClipInput();
    delete firstHandOf(input)['handednessScore'];
    expect(() => parseReplayClip(input)).toThrow(/handednessScore/);
  });

  it('rejects out-of-order frame timestamps', () => {
    const input = validClipInput();
    framesOf(input)[1]!['t'] = -1;
    expect(() => parseReplayClip(input)).toThrow(/frames\[1\]\.t/);
  });

  it('accepts the object landmark form and the nested handedness form', () => {
    const input = validClipInput();
    const hand = firstHandOf(input);
    hand['landmarks'] = Array.from({ length: LANDMARK_COUNT }, (_, i) => ({
      x: 0.5,
      y: 0.5,
      z: i * 0.01,
    }));
    hand['handedness'] = { label: 'Right', score: 0.5 };
    delete hand['handednessScore'];

    const clip = parseReplayClip(input);
    expect(clip.frames[0]!.hands[0]!.handedness).toEqual({
      label: 'Right',
      score: 0.5,
    });
    expect(clip.frames[0]!.hands[0]!.landmarks[4]!.z).toBeCloseTo(0.04, 10);
  });

  it('accepts a frame with no hands, because a hand can be legitimately absent', () => {
    const input = validClipInput();
    framesOf(input)[0]!['hands'] = [];
    const clip = parseReplayClip(input);
    expect(clip.frames[0]!.hands).toHaveLength(0);
  });
});

describe('ReplaySource', () => {
  const clip = parseReplayClip(fixture);

  it('emits nothing before start() and nothing after stop()', () => {
    const source = new ReplaySource(clip);
    expect(source.frameAt(0)).toBeNull();

    source.start(0);
    expect(source.frameAt(0)).not.toBeNull();

    source.stop();
    expect(source.frameAt(10)).toBeNull();
  });

  it('reports the clip provenance and its own id', () => {
    const source = new ReplaySource(clip);
    source.start(0);
    const frame = source.frameAt(0)!;
    expect(frame.sourceId).toBe('replay');
    expect(frame.provenance).toBe('simulated');
    expect(source.provenance).toBe('simulated');
  });

  it('stamps frames with the render clock, not the clip time, so time stays monotonic', () => {
    const source = new ReplaySource(clip);
    source.start(1000);
    // Past the end of the clip, so the clip time has wrapped but the clock has not.
    expect(source.frameAt(2500)!.timestampMs).toBe(2500);
  });

  it('selects the last frame at or before the elapsed time', () => {
    const source = new ReplaySource(clip);
    source.start(0);
    expect(source.frameIndexAt(0)).toBe(0);
    expect(source.frameIndexAt(41)).toBe(0);
    expect(source.frameIndexAt(42)).toBe(1);
    expect(source.frameIndexAt(82)).toBe(1);
    expect(source.frameIndexAt(83)).toBe(2);
    expect(source.frameIndexAt(1e9)).toBe(clip.frames.length - 1);
  });

  it('loops back to the first frame after the clip duration', () => {
    const source = new ReplaySource(clip, { loop: true });
    source.start(0);
    const first = source.frameAt(0)!.hands[0]!.landmarks[0]!;
    const wrapped = source.frameAt(clip.durationMs)!.hands[0]!.landmarks[0]!;
    expect(wrapped.x).toBeCloseTo(first.x, 12);
  });

  it('honours an explicit non-looping source by holding the final frame', () => {
    const source = new ReplaySource(clip, { loop: false });
    source.start(0);
    const lastFrame = clip.frames[clip.frames.length - 1]!;
    const held = source.frameAt(1e6)!.hands[0]!.landmarks[0]!;
    expect(held.x).toBeCloseTo(lastFrame.hands[0]!.landmarks[0]!.x, 12);
  });

  it('does not let a negative elapsed time produce a blank frame', () => {
    const source = new ReplaySource(clip);
    source.start(1000);
    const frame = source.frameAt(500)!;
    expect(frame.hands[0]!.landmarks).toHaveLength(LANDMARK_COUNT);
  });

  it('does not expose the clip array to reordering by a consumer', () => {
    const source = new ReplaySource(clip);
    source.start(0);
    const frame = source.frameAt(0)!;
    frame.hands.length = 0;
    expect(source.frameAt(0)!.hands).toHaveLength(1);
  });

  it('treats a zero-hand frame as a valid observation', () => {
    const input = validClipInput();
    framesOf(input)[0]!['hands'] = [];
    const emptyClip = parseReplayClip(input);
    const source = new ReplaySource(emptyClip);
    source.start(0);
    expect(source.frameAt(0)!.hands).toEqual([]);
  });
});
